const LayoutTerrain *world_terrain_dm(const char *name) {
    for(size_t i=0;i<sizeof(terrains)/sizeof(*terrains);++i)
        if(!strcmp(name,terrains[i].name))return &terrains[i].terrain;
    return NULL;
}
